    dict(key='25-class-1', kind='code', title='ObjectStoreContainer — both images pinned to exact versions',
         body='// ObjectStoreContainer: starts RustFS in Docker, pinned, and adds the backup user\npublic static final String STORE_IMAGE = "rustfs/rustfs:1.0.2";\npublic static final String ADMIN_IMAGE = "rustfs/rc:v0.1.36";',
         narration='The store runs in a container, from an image pinned to an exact version. [[slnc 300]] So every run uses the same software, and prints the same output.'),
    dict(key='26-class-2', kind='code', title="ObjectStoreContainer — the backup job's policy: one action",
         body='// ObjectStoreContainer: starts RustFS in Docker, pinned, and adds the backup user\nstatic String writeOnlyPolicy(String bucket) {\n    return "{\\"Version\\":\\"2012-10-17\\",\\"Statement\\":[{\\"Effect\\":\\"Allow\\",\\"Action\\":[\\"s3:PutObject\\"],"\n            + "\\"Resource\\":[\\"arn:aws:s3:::" + bucket + "/*\\"]}]}";',
         narration="The backup job's policy has one statement. [[slnc 300]] Allow put object, on the objects of one bucket. [[slnc 300]] Everything else is denied, because nothing else is allowed."),
